const title=(v:string)=>v.replaceAll("-"," ").replace(/\b\w/g,c=>c.toUpperCase());
function Btn({children,onClick,primary=false,danger=false,disabled=false}:{children:ReactNode;onClick?:()=>void;primary?:boolean;danger?:boolean;disabled?:boolean}){return <button type="button" disabled={disabled} onClick={onClick} className={`inline-flex min-h-10 items-center justify-center gap-2 rounded-xl border px-3 text-sm font-medium hover:bg-muted disabled:opacity-50 ${primary?"border-primary bg-primary text-primary-foreground":danger?"border-red-200 text-red-700":"bg-background"}`}>{children}</button>}
function Card({title:heading,children,action}:{title:string;children:ReactNode;action?:ReactNode}){return <section className="rounded-3xl border bg-card p-5 shadow-sm md:p-6"><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><h2 className="font-semibold">{heading}</h2>{action}</div>{children}</section>}
function Empty({text}:{text:string}){return <div className="rounded-2xl border border-dashed p-8 text-center text-sm text-muted-foreground">{text}</div>}
function Metric({label,value}:{label:string;value:any}){return <div className="rounded-2xl border bg-card p-5"><div className="text-xs text-muted-foreground">{label}</div><div className="mt-2 text-3xl font-semibold">{value}</div></div>}
function Input({label,value,onChange,type="text"}:{label:string;value:any;onChange:(v:string)=>void;type?:string}){return <label className="block text-sm font-medium"><span>{label}</span><input type={type} value={value??""} onChange={e=>onChange(e.target.value)} className="mt-1 h-11 w-full rounded-xl border bg-background px-3"/></label>}
function Textarea({label,value,onChange,placeholder=""}:{label:string;value:any;onChange:(v:string)=>void;placeholder?:string}){return <label className="block text-sm font-medium md:col-span-2"><span>{label}</span><textarea value={value??""} placeholder={placeholder} onChange={e=>onChange(e.target.value)} className="mt-1 min-h-28 w-full rounded-xl border bg-background p-3"/></label>}

