function SpecEditor({module,selected,token,data,setData,notify}:{module:AdminModule;selected:string;token:string;data:R;setData:(v:R)=>void;notify:(v:string)=>void}){
 const key="admin.spec."+module.id+"."+selected;
 const saved=data.settings[key]&&typeof data.settings[key]==="object"?data.settings[key]:{};
 const specs=inferFields(module,selected);
 const [draft,setDraft]=useState<R>(saved);
 useEffect(()=>setDraft(data.settings[key]&&typeof data.settings[key]==="object"?data.settings[key]:{}),[key,data.settings]);
 const update=(k:string,v:any)=>setDraft(x=>({...x,[k]:v}));
 const action=async(x:FieldSpec)=>{
   const k=x.key.toLowerCase();
   try {
    if(k.includes("exportcsv")||k.includes("exportlogs")||k.includes("export")){const rows=data.rsvps?.length?data.rsvps:(data.audit?.length?data.audit:data.backups||[]);const headers:string[]=Array.from(new Set<string>(rows.flatMap((r:any)=>Object.keys(r||{}))));const csv=[headers.join(","),...rows.map((r:any)=>headers.map(h=>JSON.stringify(r?.[h]??"")).join(","))].join("\n");const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([csv],{type:"text/csv"}));a.download=(module.id==="audit"?"audit-log":"wedding-admin")+".csv";a.click();URL.revokeObjectURL(a.href);notify("CSV exported.");return}
    if(k.includes("exportpdf")){window.print();notify("Print/PDF export opened.");return}
    if(k.includes("mark as read")){const unread=(data.notifications||[]).filter((n:any)=>!n.read_at);for(const n of unread)await markNotificationRead(token,n.id);setData({...data,notifications:(data.notifications||[]).map((n:any)=>({...n,read_at:n.read_at||new Date().toISOString()}))});notify("Unread notifications marked as read.");return}
    if(k==="delete"||k.includes("delete notification")){const target=(data.notifications||[])[0];if(target){await deleteNotification(token,target.id);setData({...data,notifications:data.notifications.filter((n:any)=>n.id!==target.id)});notify("Notification deleted.");return}}
    if(k.includes("confirm restore")||k.includes("restore full")||k.includes("restore website")||k.includes("restore media")||k.includes("restore database")||k==="restore"){const target=(data.backups||[])[0];if(!target)throw new Error("No backup is available to restore.");await restoreAdminBackup(token,target.id);notify("Selected backup restored to Draft.");return}
    if(k.includes("preview")||k==="view"||k.includes("open")){const url=Object.values(draft).find(v=>typeof v==="string"&&/^https?:\/\//i.test(v));if(url)window.open(String(url),"_blank","noopener,noreferrer");else if(module.id==="website")window.open("/?preview=draft","_blank","noopener,noreferrer");else notify("Preview is unavailable until the required resource is configured.");return}
    if(k.includes("publish now")||k==="publish"){const r=await fetch("/api/admin-advanced?action=publish",{method:"POST",headers:{Authorization:`Bearer ${token}`,"Content-Type":"application/json"},body:JSON.stringify({})});if(!r.ok)throw new Error("Publish request failed.");notify("Draft published.");return}
    if(k.includes("unpublish")){await saveSiteSetting(token,"maintenance.mode",true);notify("Public maintenance state saved; publish a new Draft to change the public site.");return}
    if(k.includes("clear")&&"caches" in window){const keys=await caches.keys();await Promise.all(keys.map(x=>caches.delete(x)));notify("Application cache cleared.");return}
    if(k.includes("update")&&"serviceWorker" in navigator){const rs=await navigator.serviceWorker.getRegistrations();await Promise.all(rs.map(x=>x.update()));notify("Service worker update requested.");return}
    if(k.includes("generate")||k.includes("secure")||k.includes("change event code")){const bytes=crypto.getRandomValues(new Uint32Array(2));const code=(bytes[0].toString(36)+bytes[1].toString(36)).slice(0,10).toUpperCase();const ev=data.events?.[0];if(ev&&k.includes("change")){await changeEventSecurityCode(token,ev,code);notify("Event security code changed.");}else if(k.includes("change all")){await changeAllEventSecurityCodes(token,code);notify("All event security codes changed.");}else update("event_security_code",code);return}
    if(k.includes("save")){await save();return}
    if(k.includes("delete guest")||k.includes("delete rsvp")){const guest=data.rsvps?.[0];if(!guest)throw new Error("No RSVP guest is available.");await deleteAdminRsvp(token,guest.id);setData({...data,rsvps:data.rsvps.filter((r:any)=>r.id!==guest.id)});notify("RSVP guest deleted.");return}
    notify(x.label+" is ready for the configured module workflow.");
   } catch(e){notify(e instanceof Error?e.message:"Action failed.");}
 };
 const save=async()=>{try{const payload={...draft,_schema:specs.map(x=>({key:x.key,label:x.label,type:x.type})),updatedAt:new Date().toISOString()};await saveSiteSetting(token,key,payload);setData({...data,settings:{...data.settings,[key]:payload}});await writeAdminAudit(token,"update_settings",key,{module:module.id,selection:selected,fields:specs.length});notify(module.label+" → "+title(selected)+" saved to Draft.");}catch(e){notify(e instanceof Error?e.message:"Unable to save Draft.")}};
 const value=(x:FieldSpec)=>{const k=x.key;if(k==="total_visitors"||k==="total")return data.analytics?.total||0;if(k==="unique_visitors"||k==="unique")return data.analytics?.unique||0;if(k==="page_views")return data.analytics?.pageViews||data.analytics?.total||0;if(k==="sessions")return data.analytics?.sessions||0;if(k==="returning_visitors"||k==="returning")return data.analytics?.returning||0;if(k==="confirmed"||k==="confirmed_guests")return (data.rsvps||[]).filter((r:any)=>r.attending===true).length;if(k==="declined"||k==="declined_guests")return (data.rsvps||[]).filter((r:any)=>r.attending===false).length;if(k==="pending"||k==="pending_guests")return (data.rsvps||[]).filter((r:any)=>r.attending==null).length;if(k==="total_guests"||k==="total_invitations")return (data.rsvps||[]).length;if(k==="plus_one"||k==="plus_one_guests")return (data.rsvps||[]).reduce((n:number,r:any)=>n+Math.max(0,Number(r.guest_count||1)-1),0);if(k==="list_all_sections_names_in_order"||k==="list_all_deleted_items")return (data.sections||[]).map((r:any)=>r.label||r.key).join("\n");if(k==="list_all_backups")return (data.backups||[]).map((r:any)=>r.label||r.id).join("\n");return draft[k]??"—"};
 return <Card title={module.label+" · "+title(selected)} action={<span className="text-xs text-muted-foreground">{specs.length} documented controls</span>}>
  <div className="mb-5 rounded-2xl border border-dashed p-4 text-sm text-muted-foreground">Each documented option is represented here with its own control type. Changes are saved as Draft and remain separate from published content until the publishing workflow is used.</div>
  <div className="grid gap-4 md:grid-cols-2">
   {specs.map(x=>{const t=x.type||"text";if(t==="action")return <div key={x.key} className="rounded-xl border p-3"><div className="mb-2 text-sm font-medium">{x.label}</div><Btn onClick={()=>void action(x)}><Check size={15}/>{x.label}</Btn></div>;
    if(t==="readonly")return <label key={x.key} className="block text-sm font-medium md:col-span-2"><span>{x.label}</span><textarea readOnly value={String(value(x))} className="mt-1 min-h-11 w-full rounded-xl border bg-muted/40 p-3"/></label>;
    if(t==="toggle")return <label key={x.key} className="flex min-h-11 items-center gap-3 rounded-xl border px-3 text-sm font-medium"><input aria-label={x.label} type="checkbox" checked={Boolean(draft[x.key])} onChange={e=>update(x.key,e.target.checked)} className="h-5 w-5"/><span>{x.label}</span></label>;
    if(t==="color")return <label key={x.key} className="block text-sm font-medium"><span>{x.label}</span><input aria-label={x.label} type="color" value={draft[x.key]||"#ffffff"} onChange={e=>update(x.key,e.target.value)} className="mt-1 h-11 w-full rounded-xl border bg-background p-1"/></label>;
    if(t==="select")return <label key={x.key} className="block text-sm font-medium"><span>{x.label}</span><select aria-label={x.label} value={draft[x.key]??""} onChange={e=>update(x.key,e.target.value)} className="mt-1 h-11 w-full rounded-xl border bg-background px-3"><option value="">Select…</option>{(x.options||["All","Enabled","Disabled"]).map(o=><option key={o} value={o}>{o}</option>)}</select></label>;
    if(t==="textarea")return <label key={x.key} className="block text-sm font-medium md:col-span-2"><span>{x.label}</span><textarea aria-label={x.label} value={draft[x.key]??""} onChange={e=>update(x.key,e.target.value)} className="mt-1 min-h-28 w-full rounded-xl border bg-background p-3"/></label>;
    return <label key={x.key} className="block text-sm font-medium"><span>{x.label}</span><input aria-label={x.label} type={t==="datetime"?"datetime-local":t} value={draft[x.key]??""} onChange={e=>update(x.key,e.target.value)} className="mt-1 h-11 w-full rounded-xl border bg-background px-3"/></label>})}
  </div>
  <div className="mt-5 flex flex-wrap gap-2"><Btn primary onClick={()=>void save()}><Check size={15}/>Save Draft</Btn><Btn onClick={()=>setDraft(saved)}><RefreshCw size={15}/>Reset</Btn></div>
 </Card>
}

function Sections({token,data,setData,notify}:any){const [rows,setRows]=useState<any[]>(data.sections||[]);useEffect(()=>setRows(data.sections||[]),[data.sections]);const move=(i:number,d:number)=>{const n=[...rows],j=i+d;if(j<0||j>=n.length)return;[n[i],n[j]]=[n[j],n[i]];setRows(n)};const save=async()=>{try{const normalized=rows.map((x,i)=>({...x,sort_order:i+1,enabled:Boolean(x.enabled)}));await supabaseRest("homepage_sections",{method:"PATCH",token,body:normalized,prefer:"return=minimal"});setData({...data,sections:normalized});notify("Section order and visibility saved to Draft.")}catch(e){notify(e instanceof Error?e.message:"Unable to save sections")}};return <Card title="Home Page Section Manager" action={<Btn primary onClick={()=>void save()}><Check size={15}/>Save Draft</Btn>}><div className="space-y-2">{rows.map((x,i)=><div key={x.key} className="flex flex-wrap items-center gap-2 rounded-xl border p-3"><div className="min-w-0 flex-1"><b>{x.label||title(x.key)}</b><div className="text-xs text-muted-foreground">{x.key}</div></div><Btn onClick={()=>setRows(r=>r.map((a,k)=>k===i?{...a,enabled:!a.enabled}:a))}>{x.enabled?<Eye size={15}/>:<EyeOff size={15}/>} {x.enabled?"Visible":"Hidden"}</Btn><Btn onClick={()=>move(i,-1)} disabled={!i}>↑</Btn><Btn onClick={()=>move(i,1)} disabled={i===rows.length-1}>↓</Btn></div>)}</div></Card>}

function Events({data,token,notify}:any){const [selected,setSelected]=useState<any>(data.events[0]||null);const [draft,setDraft]=useState<R>(selected?{...selected}:{});useEffect(()=>setDraft(selected?{...selected}:{}),[selected]);const save=async()=>{try{if(!draft.title||!draft.slug)throw new Error("Event name and slug are required.");const body={...draft,title:String(draft.title).trim(),slug:String(draft.slug).trim(),date:draft.date||null,venue_name:draft.venue_name||null,venue_address:draft.venue_address||null,maps_url:draft.maps_url||null,description:draft.description||null,visible:draft.visible!==false,event_type:draft.event_type||null,start_time:draft.start_time||null,end_time:draft.end_time||null,image_url:draft.image_url||null,security_code:draft.security_code||null,event_lock:Boolean(draft.event_lock)};await supabaseRest("events",{method:selected?"PATCH":"POST",token,query:selected?"id=eq."+selected.id:undefined,body,prefer:"return=minimal"});notify("Event saved to Draft.");}catch(e){notify(e instanceof Error?e.message:"Unable to save event")}};const generate=()=>setDraft({...draft,security_code:(crypto.getRandomValues(new Uint32Array(2))[0].toString(36)+crypto.getRandomValues(new Uint32Array(2))[0].toString(36)).slice(0,10).toUpperCase()});const fields:[string,string,string][]=[["title","Event Name","text"],["slug","Slug","text"],["event_type","Event Type","select"],["date","Event Date","date"],["start_time","Start Time","time"],["end_time","End Time","time"],["venue_name","Venue Name","text"],["venue_address","Venue Address","text"],["maps_url","Map URL","url"],["image_url","Image","url"],["security_code","Event Security Code","password"]];return <div className="grid gap-4 lg:grid-cols-[300px_1fr]"><Card title="Event List" action={<Btn onClick={()=>{setSelected(null);setDraft({title:"",slug:"",visible:true,event_lock:false})}}>Add Event</Btn>}><div className="space-y-2">{data.events.map((ev:any)=><button key={ev.id} onClick={()=>setSelected(ev)} className={"w-full rounded-xl border p-3 text-left "+(selected?.id===ev.id?"border-primary bg-primary/5":"")}><b>{ev.title}</b><div className="text-xs text-muted-foreground">{ev.date||ev.slug}</div></button>)}</div></Card><Card title="Event Information" action={<div className="flex gap-2"><Btn onClick={generate}>Generate Event Code</Btn><Btn primary onClick={()=>void save()}><Check size={15}/>Save Draft</Btn></div>}><div className="grid gap-4 md:grid-cols-2">{fields.map(([k,l,t])=><label key={k} className="text-sm font-medium"><span>{l}</span>{t==="select"?<select value={draft[k]||""} onChange={e=>setDraft({...draft,[k]:e.target.value})} className="mt-1 h-11 w-full rounded-xl border px-3"><option value="">Select event type</option>{["Wedding","Ceremony","Reception","Engagement","Other"].map(x=><option key={x}>{x}</option>)}</select>:<input type={t} value={draft[k]||""} onChange={e=>setDraft({...draft,[k]:e.target.value})} className="mt-1 h-11 w-full rounded-xl border px-3"/>}</label>)}<label className="flex min-h-11 items-center gap-2 rounded-xl border px-3 text-sm"><input type="checkbox" checked={draft.visible!==false} onChange={e=>setDraft({...draft,visible:e.target.checked})}/>Visible</label><label className="flex min-h-11 items-center gap-2 rounded-xl border px-3 text-sm"><input type="checkbox" checked={Boolean(draft.event_lock)} onChange={e=>setDraft({...draft,event_lock:e.target.checked})}/>Enable Event Lock</label><label className="md:col-span-2 text-sm font-medium"><span>Description</span><textarea value={draft.description||""} onChange={e=>setDraft({...draft,description:e.target.value})} className="mt-1 min-h-28 w-full rounded-xl border p-3"/></label></div></Card></div>}
